{
  "schema_version": "1.0",
  "review_title": "Max Payload Batch Size Conflict in VEHICLE-TELEMATICS",
  "overall_status": "blocking",
  "executive_summary": "Proposed update to Max Payload Batch Size (5.62 mb) conflicts with certified specification in DOC-TELE-602 (5.0 mb).",
  "findings": [
    {
      "finding_id": "FIND-NUM-001",
      "category": "policy_conflict",
      "severity": "medium",
      "title": "Max Payload Batch Size Exceeds Certified Threshold",
      "description": "Proposed value 5.62 mb exceeds certified 5.0 mb (+12.5% drift).",
      "evidence": [
        {
          "source": "DOC-TELE-602",
          "quote": "Vehicle upload payload batch size cannot exceed 5.0 MB. Exponential backoff maximum ceiling is strictly 60.0 seconds upo",
          "location": "Section 1"
        }
      ],
      "impact": "Breaching 5.0 mb introduces hardware overstress or operational policy failure.",
      "recommended_fix": "Maintain certified ceiling 5.0 mb or submit formal engineering sign-off.",
      "confidence": "high",
      "is_inference": false,
      "needs_human_verification": true
    }
  ],
  "missing_information": [],
  "improvements": [
    {
      "title": "Re-clamp Max Payload Batch Size",
      "description": "Restore parameter to <= 5.0 mb.",
      "linked_finding_ids": [
        "FIND-NUM-001"
      ],
      "type": "required_fix"
    }
  ],
  "assumptions": [],
  "questions_for_reviewer": [
