{
  "schema_version": "1.0",
  "review_title": "Specification Conflict in FUNCTIONAL-SAFETY",
  "overall_status": "blocking",
  "executive_summary": "Supplied documents contain conflicting tolerances. Unified 30.0 ms violates primary standard in DOC-SIL-700.",
  "findings": [
    {
      "finding_id": "FIND-CONF-001",
      "category": "policy_conflict",
      "severity": "high",
      "title": "Specification Contradiction Between DOC-SIL-700 and DOC-SIL-700-EXT",
      "description": "DOC-SIL-700-EXT allows 30.0 ms, but DOC-SIL-700 strictly caps parameter at 25.0 ms.",
      "evidence": [
        {
          "source": "DOC-SIL-700",
          "quote": "Safety supervisor watchdog heartbeat interval must not exceed 25.0 ms. Missing 3 consecuti",
          "location": "Certified Base"
        },
        {
          "source": "DOC-SIL-700-EXT",
          "quote": "Auxiliary systems permit excursions up to 30.0 ms for brief intervals.",
          "location": "Extension Clause"
        }
      ],
      "impact": "Applying unified value introduces component failure in baseline modules.",
      "recommended_fix": "Preserve module-specific limits: 25.0 ms for primary, 30.0 ms for auxiliary.",
      "confidence": "high",
      "is_inference": false,
      "needs_human_verification": true
    }
  ],
  "missing_information": [],
  "improvements": [
    {
      "title": "Decouple Module Standards",
      "description": "Maintain separate configuration keys per subsystem.",
      "linked_finding_ids": [
        "FIND-CONF-001"
      ],
      "type": "required_fix"
    }
  ],
